import { parseColumns } from "../human_table.js";
//#region src/utils/help_text.ts
const HELP_WRAP = 78;
const WRAP_INDENT = "    ";
const helpWidth = () => {
	const fromStdout = process.stdout.columns;
	if (typeof fromStdout === "number" && Number.isFinite(fromStdout) && fromStdout >= 1) return Math.max(24, fromStdout - 1);
	const fromEnv = parseColumns(process.env.COLUMNS);
	if (fromEnv !== void 0) return Math.max(24, fromEnv - 1);
	return 78;
};
const helpCsv = (label, items, width = helpWidth()) => {
	if (items.length === 0) return "";
	const prefix = `${label}:`;
	const lines = [];
	let line = prefix;
	for (const item of items) {
		const addition = line === prefix ? ` ${item}` : `, ${item}`;
		if (line.length + addition.length <= width) {
			line += addition;
			continue;
		}
		if (line === prefix) lines.push(prefix);
		else lines.push(`${line},`);
		line = `${WRAP_INDENT}${item}`;
	}
	lines.push(line);
	return lines.join("\n");
};
const wrapHelpText = (text, width) => {
	if (width < 1) return text;
	const words = text.trim().split(/\s+/).filter((word) => word !== "");
	if (words.length === 0) return text;
	const lines = [];
	let line = "";
	for (const word of words) {
		if (line === "") {
			line = word;
			continue;
		}
		if (line.length + 1 + word.length <= width) {
			line = `${line} ${word}`;
			continue;
		}
		lines.push(line);
		line = word;
	}
	if (line !== "") lines.push(line);
	return lines.join("\n");
};
const helpEpilogue = (...blocks) => ["", ...blocks.filter((block) => block !== "")].join("\n");
const globalOptionsTrailer = (usage) => {
	const cli = usage.trim().split(/\s+/)[0];
	return `Global options: see ${cli === "" ? "neon" : cli} --help`;
};
//#endregion
export { HELP_WRAP, globalOptionsTrailer, helpCsv, helpEpilogue, helpWidth, wrapHelpText };
